package employee.management.system;import java.sql.Connection;import java.sql.DriverManager;import java.sql.Statement;public class conn {    Connection connection;    Statement statement;    public conn(){        try{            Class.forName("com.mysql.cj.jdbc.Driver");            String dbPassword = System.getenv("EMP_DB_PASSWORD");            if (dbPassword == null || dbPassword.isBlank()) {                throw new IllegalStateException("EMP_DB_PASSWORD is not set");            }            connection = DriverManager.getConnection(                    "jdbc:mysql://localhost:3306/employeemanagement",                    "root",                    dbPassword            );            statement = connection.createStatement();            System.out.println("Database Connected Successfully!");        }catch (Exception e){            e.printStackTrace();        }    }    public static void main(String[] args) {        new conn();    }}